use serde_json::{json,Value};
use ulw_loop_core::quality_gate::validate_quality_gate;
fn base()->Value{json!({"manualQa":{"by":"main-session","status":"passed","evidence":"qa","surfaceEvidence":[{"id":"s","criterionRef":"C1","surface":"cli","invocation":"true","verdict":"passed","artifactRefs":["a"]}],"adversarialCases":[{"id":"x","criterionRef":"C1","scenario":"x","expectedBehavior":"x","verdict":"not_applicable","reason":"x","artifactRefs":["a"]}],"artifactRefs":[{"id":"a","kind":"cli-transcript","description":"a","path":"qa.txt"}]},"gateReview":{"by":"category:unspecified-high","recommendation":"APPROVE","reportPath":"gate.md","evidence":"gate","blockers":[]},"iteration":{"fullRerun":true,"status":"passed","rerunCommands":["true"],"evidence":"rerun"},"criteriaCoverage":{"totalCriteria":1,"passCount":1,"originalIntent":"i","desiredOutcome":"d","userOutcomeReview":"u","adversarialClassesCovered":["x"]}})}
#[test]fn accepts_without_code_review(){assert!(validate_quality_gate(&base(),None).is_ok());}
#[test]fn accepts_wrapped_and_optional_code_review(){assert!(validate_quality_gate(&json!({"qualityGate":base()}),None).is_ok());let mut x=base();x.as_object_mut().unwrap().insert("codeReview".into(),json!({"by":"lazycodex-code-reviewer","recommendation":"APPROVE","codeQualityStatus":"CLEAR","reportPath":"code.md","evidence":"review","blockers":[]}));assert!(validate_quality_gate(&x,None).is_ok());}
#[test]fn preserves_main_session_code_review(){let mut x=base();x.as_object_mut().unwrap().insert("codeReview".into(),json!({"by":"main-session","recommendation":"APPROVE","codeQualityStatus":"CLEAR","reportPath":"code.md","evidence":"review","blockers":[]}));assert_eq!(validate_quality_gate(&x,None).unwrap().code_review.unwrap().by,"main-session");}
#[test]fn rejects_random_code_review_author(){let mut x=base();x.as_object_mut().unwrap().insert("codeReview".into(),json!({"by":"random","recommendation":"APPROVE","codeQualityStatus":"CLEAR","reportPath":"code.md","evidence":"review","blockers":[]}));assert!(validate_quality_gate(&x,None).unwrap_err().message.contains("codeReview.by"));}
#[test]fn rejects_unknown_gate_acceptor(){let mut x=base();x["gateReview"]["by"]=json!("random-agent");assert!(validate_quality_gate(&x,None).unwrap_err().message.contains("gateReview.by"));}
